contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller, address newOwner) public {
        // Use the real caller as the invoker.
        // To change msg.sender for the call to c, we must call from this contract;
        // so caller must be this address for the success path.
        // For the revert path, caller must differ from current owner.
        address currentOwner = c.owner();
        address thisAddr = address(this);

        bool reverted;
        address before = c.owner();
        if (caller == thisAddr) {
            // Success path: this contract is owner only if currentOwner == thisAddr.
            // We drive with this (the only possible successful msg.sender).
            try c.setOwner(newOwner) { reverted = false; } catch { reverted = true; }
        } else {
            // Cannot change msg.sender to arbitrary caller; use this contract.
            // This path covers non-owner attempts: if currentOwner != thisAddr, this reverts.
            try c.setOwner(newOwner) { reverted = false; } catch { reverted = true; }
        }
        address after = c.owner();

        // General rule: setOwner succeeds iff the caller (this contract) is the current owner.
        // When it succeeds, owner becomes newOwner; when it reverts, owner is unchanged.
        bool callerIsOwner = (thisAddr == before);
        bool success = !reverted;
        assert(success == callerIsOwner && (success ? after == newOwner : after == before));
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner, bool callerIsOwner) public payable {
        // Bring c's owner to a known state: make this contract the owner if we want to act as owner.
        // Since this contract deployed c, it is already the owner initially.
        // If callerIsOwner is true, the test contract (msg.sender for c calls) is the owner already.
        // If false, we make a different address the owner first, so this contract is no longer owner.
        address beforeOwner = c.owner();
        if (!callerIsOwner) {
            // Change ownership away from this contract so subsequent calls are not from owner.
            c.setOwner(address(0xdead));
        }
        address ownerBefore = c.owner();

        bool reverted;
        try c.setOwner(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address ownerAfter = c.owner();

        if (callerIsOwner) {
            // When the caller is the owner, the call must succeed and the owner must become newOwner.
            assert(!reverted && ownerAfter == newOwner);
        } else {
            // When the caller is not the owner, the call must revert and the owner must not change.
            assert(reverted && ownerAfter == ownerBefore);
        }
    }
}

