    }

    function run(address newOwner1, address newOwner2) public {
        // First successful transfer: current owner is this contract (the deployer).
        bool success1 = c.setOwner(newOwner1);
        address ownerAfter1 = c.owner();

        // Second transfer: now the owner is newOwner1, so only a call from newOwner1 should succeed.
        // Since this contract is no longer the owner, the second call must revert.
        bool reverted2;
        try c.setOwner(newOwner2) {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }
        address ownerAfter2 = c.owner();

        assert(success1 && ownerAfter1 == newOwner1 && reverted2 && ownerAfter2 == newOwner1);
    }
}

