    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address newOwner) public {
        require(caller != address(0) && newOwner != address(0));

        address beforeOwner = c.owner();

        bool callerIsOwner = (caller == beforeOwner);
        bool reverted;
        bool returned;
        address afterOwner;

        if (callerIsOwner) {
            returned = c.setOwner(newOwner);
            afterOwner = c.owner();
            assert(returned == true && afterOwner == newOwner);
        } else {
            try c.setOwner(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
            afterOwner = c.owner();
            assert(reverted == true && afterOwner == beforeOwner);
        }
    }
}

